func (r *MutationResolver) CompactAssistantThread(ctx context.Context, id string) (*gqlmodel.AssistantStartedTurn, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceAssistant, permission.OpCreate)
	if err != nil {
		return nil, err
	}
	req, err := deskmapping.ThreadRequest(authCtx, "id", id)
	if err != nil {
		return nil, err
	}

	thread, err := r.AssistantService.GetThread(ctx, &req)
	if err != nil {
		return nil, err
	}
	if thread.ContextUsage != nil && !thread.ContextUsage.WorthCompacting() {
		return nil, errortypes.NewBusinessError(
			"There is nothing to compact yet. Compacting summarizes the turns before the latest two.",
		)
	}

	turn, err := assistantcontract.StartCompaction(ctx, r.AssistantTurnService, r.WorkflowStarter,
		assistantcontract.StartCompactionRequest{
			ThreadID:   thread.ID,
			TenantInfo: req.TenantInfo,
			Actor:      *actorutil.FromAuthContext(authCtx),
		})
	if err != nil {
		return nil, err
	}

	return deskmapping.StartedTurn(turn), nil
}

