func (r *QueryResolver) AssistantThreadShelves(ctx context.Context, edges []int) (any, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceAssistant, permission.OpRead)
	if err != nil {
		return nil, err
	}

	bounds := make([]int64, 0, len(edges))
	for _, edge := range edges {
		bounds = append(bounds, int64(edge))
	}

	return r.AssistantService.CountThreadShelves(ctx, &conversationports.CountThreadShelvesRequest{
		UserID:     authCtx.UserID,
		TenantInfo: resolvercore.TenantInfo(authCtx),
		Edges:      bounds,
	})
}

